func init() {
	mergeHardcodedRatioMap(defaultModelRatio, hardcodedModelsDevModelRatio)
	mergeHardcodedRatioMap(defaultCompletionRatio, hardcodedModelsDevCompletionRatio)
	mergeHardcodedRatioMap(defaultCacheRatio, hardcodedModelsDevCacheRatio)
}

func mergeHardcodedRatioMap(target, source map[string]float64) {
	for k, v := range source {
		if _, exists := target[k]; !exists {
			target[k] = v
		}
	}
}
